"""Read-only checks of train/validation CSVs: labels, duplicates, near-duplicates."""
import csv
import math
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

data_dir = Path(sys.argv[1])
csv.field_size_limit(10**7)


def load(name):
    with open(data_dir / name, encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))


train, val = load("train.csv"), load("validation.csv")
sets = {"train": train, "validation": val}


def subject(text):
    first = text.split("\n", 1)[0]
    return first[len("Subject:"):].strip() if first.startswith("Subject:") else ""


def body(text):
    return text.split("\n", 1)[1] if "\n" in text else ""


def norm(s):
    return re.sub(r"\s+", " ", s.lower()).strip()


def thread_subject(s):
    s = s.lower()
    while True:
        new = re.sub(r"^\s*(re|fw|fwd|aw)\s*:\s*|^\s*\[[^\]]*\]\s*", "", s)
        if new == s:
            break
        s = new
    return norm(s)


TOKEN = re.compile(r"[a-z0-9$']+")


def tokens(s):
    return TOKEN.findall(s.lower())


def shingles(s, k=5):
    t = tokens(s)
    return {" ".join(t[i:i + k]) for i in range(max(1, len(t) - k + 1))}


def jaccard(a, b):
    return len(a & b) / len(a | b) if a | b else 0.0


print("=" * 70)
print("1. ETYKIETY")
for name, rows in sets.items():
    raw = Counter(repr(r["label"]) for r in rows)
    empty = sum(1 for r in rows if not r["label"].strip())
    bad = [r["message_id"] for r in rows if r["label"] not in ("spam", "ham")]
    print(f"  {name}: wartości={dict(raw)}  puste={empty}  spoza(spam,ham)={len(bad)} {bad[:5]}")
    print(f"    kolumny={list(rows[0].keys())}  puste message_id={sum(1 for r in rows if not r['message_id'].strip())}")

print("=" * 70)
print("2. POWTÓRZENIA PO TREŚCI")
variants = {
    "dokładny tekst": lambda r: r["text"],
    "tekst znormalizowany (małe litery, białe znaki)": lambda r: norm(r["text"]),
    "sama treść bez tematu (znormalizowana)": lambda r: norm(body(r["text"])),
}
for vname, key in variants.items():
    print(f"  -- {vname}")
    for name, rows in sets.items():
        groups = defaultdict(list)
        for r in rows:
            groups[key(r)].append((r["message_id"], r["label"]))
        dups = [g for g in groups.values() if len(g) > 1]
        print(f"    w obrębie {name}: grup powtórzeń={len(dups)} {dups[:5]}")
    tkeys = defaultdict(list)
    for r in train:
        tkeys[key(r)].append((r["message_id"], r["label"]))
    cross = [(r["message_id"], r["label"], tkeys[key(r)]) for r in val if key(r) in tkeys]
    print(f"    train <-> validation: {len(cross)} {cross[:5]}")

print("  -- ten sam temat (dokładnie)")
for name, rows in sets.items():
    c = Counter(subject(r["text"]) for r in rows)
    print(f"    w obrębie {name}: {[(s, n) for s, n in c.items() if n > 1]}")

print("=" * 70)
print("3. PODOBIEŃSTWO WALIDACJA -> TRENING")

# 3a. Jaccard on 5-word shingles of the body (detects copied/templated passages)
tsh = {r["message_id"]: shingles(body(r["text"])) for r in train}
tlab = {r["message_id"]: r["label"] for r in train}
tsub = {r["message_id"]: subject(r["text"]) for r in train}

# 3b. TF-IDF cosine on word unigrams of full text, IDF fitted on train only
df = Counter()
for r in train:
    df.update(set(tokens(r["text"])))
N = len(train)
idf = {w: math.log((1 + N) / (1 + d)) + 1 for w, d in df.items()}


def tfidf(text):
    tf = Counter(w for w in tokens(text) if w in idf)
    v = {w: c * idf[w] for w, c in tf.items()}
    n = math.sqrt(sum(x * x for x in v.values())) or 1.0
    return {w: x / n for w, x in v.items()}


tvec = {r["message_id"]: tfidf(r["text"]) for r in train}


def cos(a, b):
    if len(a) > len(b):
        a, b = b, a
    return sum(x * b.get(w, 0.0) for w, x in a.items())


results = []
for r in val:
    vs = shingles(body(r["text"]))
    vv = tfidf(r["text"])
    bj = max(((jaccard(vs, s), mid) for mid, s in tsh.items()))
    bc = max(((cos(vv, v), mid) for mid, v in tvec.items()))
    results.append((r, bj, bc))


def bucket(vals, edges):
    out = []
    for lo in edges:
        out.append(f">= {lo}: {sum(1 for x in vals if x >= lo)}")
    return ", ".join(out)


print("  Rozkład maks. Jaccard (5-gramy słów treści) na wiadomość walidacyjną:")
print("   ", bucket([j for _, (j, _), _ in results], [0.9, 0.5, 0.3, 0.2, 0.1]))
print("  Rozkład maks. cosinus TF-IDF (słowa, IDF z train) na wiadomość walidacyjną:")
print("   ", bucket([c for _, _, (c, _) in results], [0.9, 0.8, 0.7, 0.6, 0.5]))

print("  Najbardziej podobne pary (sortowane po max(Jaccard, cosinus)):")
results.sort(key=lambda x: -max(x[1][0], x[2][0]))
for r, (j, jm), (c, cm) in results[:15]:
    print(f"    val {r['message_id']} [{r['label']}] '{subject(r['text'])[:55]}'")
    print(f"       Jaccard={j:.2f} -> {jm} [{tlab[jm]}] '{tsub[jm][:55]}'")
    print(f"       cosinus={c:.2f} -> {cm} [{tlab[cm]}] '{tsub[cm][:55]}'")

# 3c. Same thread (subject without Re:/Fwd:/[list] tags)
print("  Wspólne wątki (temat bez Re:/Fwd:/[lista]) train <-> validation:")
tthreads = defaultdict(list)
for r in train:
    t = thread_subject(subject(r["text"]))
    if t:
        tthreads[t].append((r["message_id"], r["label"]))
shared = [(r["message_id"], r["label"], thread_subject(subject(r["text"])), tthreads[thread_subject(subject(r["text"]))])
          for r in val if thread_subject(subject(r["text"])) in tthreads]
print(f"    liczba: {len(shared)}")
for s in shared:
    print(f"     {s}")
for name, rows in sets.items():
    c = Counter(thread_subject(subject(r["text"])) for r in rows)
    print(f"    wątki powtórzone w obrębie {name}: {[(s, n) for s, n in c.items() if n > 1]}")

# 3d. Mailing-list tags as potential shortcut features
print("  Tagi list [xxx] w temacie wg etykiety:")
for name, rows in sets.items():
    c = Counter()
    for r in rows:
        for tag in re.findall(r"\[([^\]]+)\]", subject(r["text"])):
            c[(tag, r["label"])] += 1
    print(f"    {name}: {sorted(c.items(), key=lambda x: -x[1])[:12]}")

